-- scripts/asaas/migracao-asaas.sql — Asaas SÓ LEITURA, DSHOWDASH. SÓ ADITIVA (CREATE TABLE IF NOT EXISTS). Gerada de AsaasEsquema::ddl('') — não editar à mão.
-- Aplicar SÓ no portão (root do MySQL por arquivo). Reverter = RENAME TABLE para *_revertido_<ts> (nada é apagado).
CREATE TABLE IF NOT EXISTS `asaas_contas` (`conta` VARCHAR(32) NOT NULL, `nome` VARCHAR(120) NULL, `ambiente` VARCHAR(10) NOT NULL DEFAULT 'producao', `estado` VARCHAR(20) NOT NULL DEFAULT 'nunca', `erro_codigo` VARCHAR(40) NULL, `ultima_tentativa` DATETIME NULL, `geracao_ativa` TINYINT NULL, `execucao_ativa` BIGINT UNSIGNED NULL, `ultima_sync_ok` DATETIME NULL, `saldo` DECIMAL(15,2) NULL, `saldo_em` DATETIME NULL, `atualizado_em` DATETIME NOT NULL, PRIMARY KEY (`conta`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `asaas_cobrancas` (`conta` VARCHAR(32) NOT NULL, `geracao` TINYINT NOT NULL, `payment_id` VARCHAR(40) NOT NULL, `status` VARCHAR(40) NOT NULL, `billing_type` VARCHAR(24) NULL, `valor` DECIMAL(15,2) NOT NULL, `valor_liquido` DECIMAL(15,2) NULL, `vencimento` DATE NULL, `data_criacao` DATE NULL, `data_pagamento` DATE NULL, `data_credito` DATE NULL, `cliente_id` VARCHAR(40) NULL, `deletada` TINYINT(1) NOT NULL DEFAULT 0, `presente` TINYINT(1) NOT NULL DEFAULT 1, `execucao` BIGINT UNSIGNED NOT NULL, `atualizado_em` DATETIME NOT NULL, PRIMARY KEY (`conta`, `geracao`, `payment_id`), KEY `ix_status` (`conta`, `geracao`, `status`), KEY `ix_pagamento` (`conta`, `geracao`, `data_pagamento`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `asaas_extrato` (`conta` VARCHAR(32) NOT NULL, `transacao_id` VARCHAR(40) NOT NULL, `tipo` VARCHAR(60) NULL, `valor` DECIMAL(15,2) NOT NULL, `saldo` DECIMAL(15,2) NULL, `data` DATE NULL, `payment_id` VARCHAR(40) NULL, `execucao` BIGINT UNSIGNED NOT NULL, `atualizado_em` DATETIME NOT NULL, PRIMARY KEY (`conta`, `transacao_id`), KEY `ix_data` (`conta`, `data`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `asaas_estatisticas` (`conta` VARCHAR(32) NOT NULL, `geracao` TINYINT NOT NULL, `chave` VARCHAR(20) NOT NULL, `quantidade` INT NOT NULL, `valor` DECIMAL(15,2) NOT NULL, `valor_liquido` DECIMAL(15,2) NULL, `consultado_em` DATETIME NOT NULL, PRIMARY KEY (`conta`, `geracao`, `chave`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `asaas_execucoes` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `conta` VARCHAR(32) NOT NULL, `geracao` TINYINT NULL, `inicio` DATETIME NOT NULL, `fim` DATETIME NULL, `resultado` VARCHAR(10) NOT NULL DEFAULT 'andamento', `erro_codigo` VARCHAR(40) NULL, `requisicoes` INT NOT NULL DEFAULT 0, `cobrancas` INT NOT NULL DEFAULT 0, `extrato` INT NOT NULL DEFAULT 0, PRIMARY KEY (`id`), KEY `ix_conta` (`conta`, `inicio`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
